show() {
  if (this.active) {
    return;
  }
  this.active = true;
  this.element.hidden = false;
  showElement(this.element);
  // Make picker buttons not focusable via Tab
  const buttons = [
    this.controls.prevButton,
    this.controls.nextButton,
    this.controls.viewSwitch,
    this.controls.todayButton,
    this.controls.clearButton,
  ];
  buttons.forEach(button => {
    if (button) {
      button.dataset.originalTabindex = button.getAttribute('tabindex');
      button.setAttribute('tabindex', '-1');
    }
  });
  registerListeners(this, [
    [this.element, 'keydown', onKeydown.bind(null, this)],
    [this.element, 'click', onClick.bind(null, this)],
  ]);
  this.place();
}

