edits.after:
hide() {
  if (!this.active) {
    return;
  }
  this.active = false;
  hideElement(this.element);
  // Restore tabindex on picker buttons
  const buttons = [
    this.controls.prevButton,
    this.controls.nextButton,
    this.controls.viewSwitch,
    this.controls.todayButton,
    this.controls.clearButton,
  ];
  buttons.forEach(button => {
    if (button) {
      const original = button.dataset.originalTabindex;
      if (original !== undefined) {
        button.setAttribute('tabindex', original);
      } else {
        button.removeAttribute('tabindex');
      }
      delete button.dataset.originalTabindex;
    }
  });
  unregisterListeners(this);
}
